package edu.pe.cibertec.saibm.membresia.infrastructure.persistence;
import java.time.Instant; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface AssignmentJpaRepository extends JpaRepository<AssignmentJpaEntity,UUID>{@Query("select a from AssignmentJpaEntity a where a.idempotencyKey=:key")Optional<AssignmentJpaEntity> byKey(@Param("key")String key);@Query("select a from AssignmentJpaEntity a where a.userId=:user and a.active=true and a.validFrom<=:at and (a.validUntil is null or a.validUntil>:at)")Optional<AssignmentJpaEntity> active(@Param("user")String user,@Param("at")Instant at);@Query("select a from AssignmentJpaEntity a where a.active=true and a.validUntil<=:at")List<AssignmentJpaEntity> expiring(@Param("at")Instant at);@Modifying @Query(value="insert into membership_assignments(id,user_id,plan_id,plan_code,plan_version,reservation_limit,valid_from,valid_until,active,idempotency_key,request_hash,legacy_user_id) values(:id,:user,:plan,:code,:version,:limit,:from,:until,true,:key,:hash,:legacy) on conflict(idempotency_key) do nothing",nativeQuery=true)int insert(@Param("id")UUID id,@Param("user")String user,@Param("plan")UUID plan,@Param("code")String code,@Param("version")int version,@Param("limit")int limit,@Param("from")Instant from,@Param("until")Instant until,@Param("key")String key,@Param("hash")String hash,@Param("legacy")String legacy);}
